@container
class Bidirectional:
	"""Creates a bidirectional bulk signal according to bitfield identifier
of a register definition which maps directly to a n bit wide I/O port.
When collected using the PinCollector class below, the assignments are
made according to the pin mapping"""

	_inputs = [ "pin" ]
	_outputs = [ "pout" ]
	_other = []

	def __init__(self, register, bits):
		self._field = bits
		self._register = register
		bfn = register.bfmap[bits].size()
		if bfn == 1:
			w =  bool(), bool()
		else:
			w =  intbv()[bfn:], intbv()[bfn:]

		self.pin = Signal(w[0])
		self.pout = Signal(w[1])

	@hdlmacro
	def wireup(self, _in, _out):
		yield [
			self.pin.wireup(_out),
			_in.wireup(self.pout)
		]
		
class Lookup:
	def __init__(self, rmap):
		for k, i in rmap.items():
			setattr(self, i[0], k[0])

	def iterate(self):
		for k, i in self.__dict__.items():
			yield k, i


class Rego600_Device:
	"The pin mapping of the I/O ports of the Rego600 hardware"
	# This is just a Port mockup. Use the one from the rego600 clone project
	from cpu8051.sfr8051_nxp_80c552 import rmap_sfr_8xc552 as rmap_sfr

	BIDIR, IN, OUT = range(3)

	PINMAP = {

		'p0' : [
			( 'AD0', BIDIR),
			( 'AD1', BIDIR),
			( 'AD2', BIDIR),
			( 'AD3', BIDIR),
			( 'AD4', BIDIR),
			( 'AD5', BIDIR),
			( 'AD6', BIDIR),
			( 'AD7', BIDIR),
		],

		'p1' : [
			( 'UNUSED4', BIDIR),
			( 'DS1302_D', IN),
			( 'UNUSED5', BIDIR),
			( 'SCLK', OUT),
			( '4094_D', OUT),
			( '4021_D', IN),
			( 'I2C_SCL', BIDIR),
			( 'I2C_SDA', BIDIR),
		],


		'p2' : [
			( 'A15', OUT),
			( 'A14', OUT),
			( 'A13', OUT),
			( 'A12', OUT),
			( 'A11', OUT),
			( 'A10', OUT),
			( 'A9', OUT),
			( 'A8', OUT),
		],

		'p3' : [
			( 'RXD', IN),
			( 'TXD', OUT),
			( 'INT_', IN),
			( 'INT1_', IN),
			( 'T0', IN),
			( 'T1',  IN),
			( 'WR_', OUT),
			( 'RD_', OUT),
		],

		'p4' : [
			( 'FLASH_CS', OUT),
			( 'TC_STB_DS1302_CS', OUT),
			( 'SRAM_CS', OUT),
			( 'UNUSED', OUT),
			( '4094_LAT', OUT),
			( '4021_LAT', OUT),
			( 'UNUSED2', OUT),
			( '4021_CLK', OUT),
		]
	}


	lookup = Lookup(rmap_sfr.register_map)

	regmap = lambda MAP, name : [ BF(x[0], i, i, flags = x[1]) \
		for i, x in enumerate(MAP[name]) ]

	Reg_p0 = Reg(8, regmap(PINMAP, 'p0'))
	Reg_p1 = Reg(8, regmap(PINMAP, 'p1'))
	Reg_p2 = Reg(8, regmap(PINMAP, 'p2'))
	Reg_p3 = Reg(8, regmap(PINMAP, 'p3'))
	Reg_p4 = Reg(8, regmap(PINMAP, 'p4'))


class PinCollector:
	def __init__(self, port, reverse = False):
		self.port = port
		self._reverse = reverse

	@hdlmacro
	def collect(self, *items):
		d = {}
		first = iter(items)

		expected = next(first)._register


		if self._reverse:
			for i in items:
				if i._register != expected:
					raise ValueError("Collected fields must link to the same register")

				yield [ i.pout.wireup(self.port[expected.bfmap[i._field].as_slice()]) ]
		else:
			# Wire all inputs to the given port bits
			# By default, those not specified will be tied to 0.
			for i in items:
				d[i._field] = i.pin
				if i._register != expected:
					raise ValueError("Collected fields must link to the same register")

			yield [ self.port.wireup(expected.compose(**d)) ]
		

